INSERT INTO flashcards (id, deck_id, front_text, back_text, phonetic, example_text, hint, note, card_order, is_active, created_by, created_at, updated_at) VALUES
  (20001, 2001, 'Keyboard', 'bàn phím', '/ˈkiː.bɔːd/', 'Press the enter key on your keyboard to continue.', 'n. | Computers - Electronics', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 2, 1, @admin_id, NOW(), NOW()),
  (20002, 2001, 'Monitor', 'màn hình máy tính', '/ˈmɒn.ɪ.tər/', 'The graphics designer uses a dual monitor setup.', 'n. | Computers - Electronics', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 3, 1, @admin_id, NOW(), NOW()),
  (20003, 2001, 'Printer', 'máy in', '/ˈprɪn.tər/', 'Please send the report to the office printer.', 'n. | Computers - Electronics', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 4, 1, @admin_id, NOW(), NOW()),
  (20004, 2001, 'Scanner', 'máy quét tài liệu', '/ˈskæn.ər/', 'Use the scanner to save a digital copy of the contract.', 'n. | Computers - Electronics', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 5, 1, @admin_id, NOW(), NOW()),
  (20005, 2001, 'Software', 'phần mềm', '/ˈsɒft.weər/', 'We installed new accounting software yesterday.', 'n. | Computers - Electronics', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 6, 1, @admin_id, NOW(), NOW()),
  (20006, 2001, 'Screen', 'màn hình', '/skriːn/', 'Adjust the brightness of your display screen.', 'n. | Computers - Electronics', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 11, 1, @admin_id, NOW(), NOW()),
  (20007, 2001, 'Battery', 'pin, ắc quy', '/ˈbæt.ər.i/', 'The laptop battery lasts for over eight hours.', 'n. | Computers - Electronics', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 12, 1, @admin_id, NOW(), NOW()),
  (20008, 2001, 'Cable', 'dây cáp', '/ˈkeɪ.bəl/', 'Connect the network cable to your computer.', 'n. | Computers - Electronics', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 13, 1, @admin_id, NOW(), NOW()),
  (20009, 2001, 'Device', 'thiết bị', '/dɪˈvaɪs/', 'This electronic device saves energy.', 'n. | Computers - Electronics', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 14, 1, @admin_id, NOW(), NOW()),
  (20010, 2002, 'Courier', 'dịch vụ chuyển phát nhanh', '/ˈkʊr.i.ər/', 'The courier delivered the urgent document this morning.', 'n. | Correspondence', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 4, 1, @admin_id, NOW(), NOW()),
  (20011, 2002, 'Postage', 'bưu phí', '/ˈpəʊ.stɪdʒ/', 'How much postage is required for international mail?', 'n. | Correspondence', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 5, 1, @admin_id, NOW(), NOW()),
  (20012, 2002, 'Inquiry', 'thư hỏi hàng / thắc mắc', '/ɪnˈkwaɪə.ri/', 'We received a client inquiry regarding product pricing.', 'n. | Correspondence', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 7, 1, @admin_id, NOW(), NOW()),
  (20013, 2002, 'Reply', 'trả lời, hồi đáp', '/rɪˈplaɪ/', 'Please reply to the manager email promptly.', 'v. | Correspondence', 'POS: v. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 8, 1, @admin_id, NOW(), NOW()),
  (20014, 2002, 'Stamp', 'con tem bưu điện', '/stæmp/', 'Attach a postage stamp to the top right corner.', 'n. | Correspondence', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 11, 1, @admin_id, NOW(), NOW()),
  (20015, 2002, 'Express mail', 'thư chuyển phát nhanh', '/ɪkˈspres meɪl/', 'We sent the contract via express mail.', 'n. | Correspondence', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 12, 1, @admin_id, NOW(), NOW()),
  (20016, 2002, 'Folder', 'bìa hồ sơ, kẹp tài liệu', '/ˈfəʊl.dər/', 'Place the correspondence in the red folder.', 'n. | Correspondence', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 13, 1, @admin_id, NOW(), NOW()),
  (20017, 2002, 'Forward', 'chuyển tiếp thư', '/ˈfɔː.wəd/', 'Forward the message to the sales department.', 'v. | Correspondence', 'POS: v. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 14, 1, @admin_id, NOW(), NOW()),
  (20018, 2002, 'Draft', 'bản thảo', '/drɑːft/', 'She prepared the first draft of the letter.', 'n. | Correspondence', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 15, 1, @admin_id, NOW(), NOW()),
  (20019, 2003, 'Broadcast', 'chương trình phát sóng', '/ˈbrɔːd.kɑːst/', 'The news broadcast started at six o''clock.', 'n. | Media', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 1, 1, @admin_id, NOW(), NOW()),
  (20020, 2003, 'Commercial', 'quảng cáo trên truyền hình', '/kəˈmɜː.ʃəl/', 'Our team created a 30-second TV commercial.', 'n. | Media', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 4, 1, @admin_id, NOW(), NOW()),
  (20021, 2003, 'Reporter', 'phóng viên', '/rɪˈpɔː.tər/', 'The news reporter interviewed the company president.', 'n. | Media', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 5, 1, @admin_id, NOW(), NOW()),
  (20022, 2003, 'Editor', 'biên tập viên', '/ˈed.ɪ.tər/', 'The Chief Editor reviewed the article before publication.', 'n. | Media', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 6, 1, @admin_id, NOW(), NOW()),
  (20023, 2003, 'Headline', 'tiêu đề bài báo', '/ˈhed.laɪn/', 'The breakthrough made front-page news headlines.', 'n. | Media', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 7, 1, @admin_id, NOW(), NOW()),
  (20024, 2003, 'Interview', 'cuộc phỏng vấn', '/ˈɪn.tə.vjuː/', 'The CEO gave a live radio interview.', 'n. | Media', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 9, 1, @admin_id, NOW(), NOW()),
  (20025, 2003, 'Article', 'bài báo, bài viết', '/ˈɑː.tɪ.kəl/', 'Read the latest article in today newspaper.', 'n. | Media', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 10, 1, @admin_id, NOW(), NOW()),
  (20026, 2003, 'Channel', 'kênh truyền hình', '/ˈtʃæn.əl/', 'Switch to channel 5 to watch the news.', 'n. | Media', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 11, 1, @admin_id, NOW(), NOW()),
  (20027, 2003, 'Audience', 'thính giả, khán giả', '/ˈɔː.di.əns/', 'The speaker addressed a large conference audience.', 'n. | Media', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 12, 1, @admin_id, NOW(), NOW()),
  (20028, 2003, 'Press', 'báo chí, giới truyền thông', '/pres/', 'The company held a press release conference.', 'n. | Media', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 13, 1, @admin_id, NOW(), NOW()),
  (20029, 2003, 'Publication', 'ấn phẩm, sự xuất bản', '/ˌpʌb.lɪˈkeɪ.ʃən/', 'This magazine is a popular monthly publication.', 'n. | Media', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 14, 1, @admin_id, NOW(), NOW()),
  (20030, 2004, 'Abide by', 'tuân theo, tôn trọng contract', '/əˈbaɪd baɪ/', 'Both parties agreed to abide by the contract terms.', 'v. | Contracts', 'POS: v. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 1, 1, @admin_id, NOW(), NOW()),
  (20031, 2004, 'Agreement', 'hợp đồng, sự thỏa thuận', '/əˈɡriː.mənt/', 'They signed a formal legal agreement yesterday.', 'n. | Contracts', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 2, 1, @admin_id, NOW(), NOW()),
  (20032, 2004, 'Obligation', 'nghĩa vụ, trách nhiệm', '/ˌɒb.lɪˈɡeɪ.ʃən/', 'The tenant fulfilled all contractual obligations.', 'n. | Contracts', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 4, 1, @admin_id, NOW(), NOW()),
  (20033, 2004, 'Clause', 'điều khoản', '/klɔːz/', 'Check clause 4 regarding termination rules.', 'n. | Contracts', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 6, 1, @admin_id, NOW(), NOW()),
  (20034, 2004, 'Party', 'bên tham gia hợp đồng', '/ˈpɑː.ti/', 'Each party received a signed copy.', 'n. | Contracts', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 8, 1, @admin_id, NOW(), NOW()),
  (20035, 2004, 'Expiration', 'sự hết hạn', '/ˌek.spɪˈreɪ.ʃən/', 'Renew the lease before its expiration date.', 'n. | Contracts', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 11, 1, @admin_id, NOW(), NOW()),
  (20036, 2004, 'Binding', 'có tính ràng buộc pháp lý', '/ˈbaɪn.dɪŋ/', 'This agreement is legally binding on both sides.', 'adj. | Contracts', 'POS: adj. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 13, 1, @admin_id, NOW(), NOW()),
  (20037, 2004, 'Cancel', 'hủy bỏ', '/ˈkæn.səl/', 'You may cancel the agreement within 30 days.', 'v. | Contracts', 'POS: v. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 15, 1, @admin_id, NOW(), NOW()),
  (20038, 2005, 'Candidate', 'ứng viên', '/ˈkæn.dɪ.dət/', 'We interviewed three qualified candidates today.', 'n. | Applying and Interviewing', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 3, 1, @admin_id, NOW(), NOW()),
  (20039, 2005, 'Qualifications', 'bằng cấp, năng lực', '/ˌkwɒl.ɪ.fɪˈkeɪ.ʃənz/', 'She possesses excellent academic qualifications.', 'n. | Applying and Interviewing', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 4, 1, @admin_id, NOW(), NOW()),
  (20040, 2005, 'Requirement', 'yêu cầu công việc', '/rɪˈkwaɪə.mənt/', 'Fluency in English is a key job requirement.', 'n. | Applying and Interviewing', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 5, 1, @admin_id, NOW(), NOW()),
  (20041, 2005, 'Reference', 'thư giới thiệu / người tham chiếu', '/ˈref.ər.əns/', 'Please provide two professional references.', 'n. | Applying and Interviewing', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 6, 1, @admin_id, NOW(), NOW()),
  (20042, 2005, 'Background', 'lý lịch, kinh nghiệm tích lũy', '/ˈbæk.ɡraʊnd/', 'He has a strong background in sales.', 'n. | Applying and Interviewing', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 7, 1, @admin_id, NOW(), NOW()),
  (20043, 2005, 'Skill', 'kỹ năng', '/skɪl/', 'Computer skills are essential for this role.', 'n. | Applying and Interviewing', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 9, 1, @admin_id, NOW(), NOW()),
  (20044, 2005, 'Experience', 'kinh nghiệm làm việc', '/ɪkˈspɪə.ri.əns/', 'Applicants need five years of marketing experience.', 'n. | Applying and Interviewing', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 10, 1, @admin_id, NOW(), NOW()),
  (20045, 2005, 'Interviewee', 'người được phỏng vấn', '/ˌɪn.tə.vjuːˈiː/', 'The interviewee answered all questions confidently.', 'n. | Applying and Interviewing', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 12, 1, @admin_id, NOW(), NOW()),
  (20046, 2005, 'Interviewer', 'người phỏng vấn', '/ˈɪn.tə.vjuː.ər/', 'The interviewer took notes during the meeting.', 'n. | Applying and Interviewing', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 13, 1, @admin_id, NOW(), NOW()),
  (20047, 2005, 'Position', 'vị trí công việc', '/pəˈzɪʃ.ən/', 'Apply now for the open manager position.', 'n. | Applying and Interviewing', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 14, 1, @admin_id, NOW(), NOW()),
  (20048, 2005, 'Submit', 'nộp đơn / nộp hồ sơ', '/səbˈmɪt/', 'Submit your application before Friday.', 'v. | Applying and Interviewing', 'POS: v. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 15, 1, @admin_id, NOW(), NOW()),
  (20049, 2006, 'Onboarding', 'quy trình đón tiếp nhân viên mới', '/ˈɒnˌbɔː.dɪŋ/', 'New hires complete a two-day onboarding session.', 'n. | Hiring', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 2, 1, @admin_id, NOW(), NOW()),
  (20050, 2006, 'Probation', 'thời gian thử việc', '/prəˈbeɪ.ʃən/', 'Employees serve a three-month probation period.', 'n. | Hiring', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 3, 1, @admin_id, NOW(), NOW());
INSERT INTO flashcards (id, deck_id, front_text, back_text, phonetic, example_text, hint, note, card_order, is_active, created_by, created_at, updated_at) VALUES
  (20051, 2006, 'Headhunter', 'chuyên viên săn nhân sự cấp cao', '/ˈhedˌhʌn.tər/', 'A headhunter contacted her for an executive role.', 'n. | Hiring', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 4, 1, @admin_id, NOW(), NOW()),
  (20052, 2006, 'Staffing', 'sự bố trí nhân sự', '/ˈstɑː.fɪŋ/', 'The staffing agency filled the vacant roles.', 'n. | Hiring', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 5, 1, @admin_id, NOW(), NOW()),
  (20053, 2006, 'Vacancy', 'vị trí còn trống', '/ˈveɪ.kən.si/', 'There is a vacancy in the sales department.', 'n. | Hiring', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 6, 1, @admin_id, NOW(), NOW()),
  (20054, 2006, 'Hire', 'thuê, tuyển dụng', '/haɪər/', 'The company hired a new financial manager.', 'v. | Hiring', 'POS: v. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 7, 1, @admin_id, NOW(), NOW()),
  (20055, 2006, 'Employment', 'việc làm, sự thuê lao động', '/ɪmˈplɔɪ.mənt/', 'The factory offers full-time employment.', 'n. | Hiring', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 8, 1, @admin_id, NOW(), NOW()),
  (20056, 2006, 'Payroll', 'bảng lương công ty', '/ˈpeɪ.rəʊl/', 'New staff are added to the official payroll.', 'n. | Hiring', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 9, 1, @admin_id, NOW(), NOW()),
  (20057, 2006, 'Offer letter', 'thư mời nhận việc', '/ˈɒf.ər ˈlet.ər/', 'She accepted the official job offer letter.', 'n. | Hiring', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 12, 1, @admin_id, NOW(), NOW()),
  (20058, 2006, 'Talent', 'nhân tài, người có tài', '/ˈtæl.ənt/', 'Our firm attracts top software talent.', 'n. | Hiring', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 13, 1, @admin_id, NOW(), NOW()),
  (20059, 2007, 'Instructor', 'người hướng dẫn', '/ɪnˈstrʌk.tər/', 'The instructor explained the safety procedures.', 'n. | Training', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 2, 1, @admin_id, NOW(), NOW()),
  (20060, 2007, 'Module', 'học phần, mô-đun đào tạo', '/ˈmɒd.juːl/', 'Complete online training module 1 first.', 'n. | Training', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 3, 1, @admin_id, NOW(), NOW()),
  (20061, 2007, 'Trainee', 'thực tập sinh / người được đào tạo', '/ˌtreɪ.niː/', 'Each trainee received a study handbook.', 'n. | Training', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 6, 1, @admin_id, NOW(), NOW()),
  (20062, 2007, 'Coach', 'huấn luyện viên', '/kəʊtʃ/', 'The executive coach assisted the team.', 'n. | Training', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 7, 1, @admin_id, NOW(), NOW()),
  (20063, 2007, 'Skillset', 'tập hợp kỹ năng', '/ˈskɪl.set/', 'Training improves your technical skillset.', 'n. | Training', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 8, 1, @admin_id, NOW(), NOW()),
  (20064, 2007, 'Session', 'buổi học / phiên đào tạo', '/ˈseʃ.ən/', 'The morning training session lasts two hours.', 'n. | Training', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 12, 1, @admin_id, NOW(), NOW()),
  (20065, 2007, 'Practice', 'sự luyện tập, thực hành', '/ˈpræk.tɪs/', 'Regular practice enhances fluency.', 'n. | Training', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 13, 1, @admin_id, NOW(), NOW()),
  (20066, 2007, 'Improvement', 'sự cải thiện, nâng cao', '/ɪmˈpruːv.mənt/', 'We noticed a major improvement in efficiency.', 'n. | Training', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 14, 1, @admin_id, NOW(), NOW()),
  (20067, 2008, 'Procedure', 'quy trình làm việc', '/prəˈsiː.dʒər/', 'Follow standard office filing procedures.', 'n. | Office Procedures', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 1, 1, @admin_id, NOW(), NOW()),
  (20068, 2008, 'Filing', 'sự lưu trữ hồ sơ', '/ˈfaɪ.lɪŋ/', 'The receptionist handles daily document filing.', 'n. | Office Procedures', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 3, 1, @admin_id, NOW(), NOW()),
  (20069, 2008, 'Workflow', 'luồng công việc', '/ˈwɜːk.fləʊ/', 'Automation streamlined our administrative workflow.', 'n. | Office Procedures', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 4, 1, @admin_id, NOW(), NOW()),
  (20070, 2008, 'Shredder', 'máy hủy tài liệu', '/ˈʃred.ər/', 'Dispose of confidential papers using the shredder.', 'n. | Office Procedures', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 6, 1, @admin_id, NOW(), NOW()),
  (20071, 2008, 'Stationery', 'văn phòng phẩm', '/ˈsteɪ.ʃən.ər.i/', 'Order extra pens and paper from office stationery.', 'n. | Office Procedures', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 7, 1, @admin_id, NOW(), NOW()),
  (20072, 2008, 'Inventory', 'sự kiểm kê vật tư', '/ˈɪn.vən.tər.i/', 'We conduct monthly office supply inventory.', 'n. | Office Procedures', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 8, 1, @admin_id, NOW(), NOW()),
  (20073, 2008, 'Requisition', 'đơn yêu cầu cấp vật tư', '/ˌrek.wɪˈzɪʃ.ən/', 'Submit a supply requisition form to manager.', 'n. | Office Procedures', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 9, 1, @admin_id, NOW(), NOW()),
  (20074, 2008, 'Schedule', 'lịch trình công việc', '/ˈʃed.juːl/', 'Check the weekly office meeting schedule.', 'n. | Office Procedures', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 11, 1, @admin_id, NOW(), NOW()),
  (20075, 2008, 'Duplicate', 'bản sao', '/ˈdʒuː.plɪ.keɪt/', 'Keep a duplicate copy of the invoice.', 'n. | Office Procedures', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 12, 1, @admin_id, NOW(), NOW()),
  (20076, 2008, 'Stamp', 'đóng dấu văn bản', '/stæmp/', 'Stamp the document approved before filing.', 'v. | Office Procedures', 'POS: v. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 13, 1, @admin_id, NOW(), NOW()),
  (20077, 2008, 'Routine', 'thói quen / công việc thường nhật', '/ruːˈtiːn/', 'Morning email review is part of her daily routine.', 'n. | Office Procedures', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 15, 1, @admin_id, NOW(), NOW()),
  (20078, 2009, 'Salary', 'tiền lương cố định', '/ˈsæl.ər.i/', 'Salaries are paid on the last working day.', 'n. | Salaries and Benefits', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 1, 1, @admin_id, NOW(), NOW()),
  (20079, 2009, 'Insurance', 'bảo hiểm', '/ɪnˈʃɔː.rəns/', 'Health insurance covers medical and dental care.', 'n. | Salaries and Benefits', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 4, 1, @admin_id, NOW(), NOW()),
  (20080, 2009, 'Pension', 'lương hưu', '/ˈpen.ʃən/', 'Retirees receive monthly pension payments.', 'n. | Salaries and Benefits', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 5, 1, @admin_id, NOW(), NOW()),
  (20081, 2009, 'Overtime', 'giờ làm thêm', '/ˈəʊ.və.taɪm/', 'Workers earn extra pay for working overtime.', 'n. | Salaries and Benefits', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 7, 1, @admin_id, NOW(), NOW()),
  (20082, 2009, 'Deduction', 'khoản khấu trừ lương', '/dɪˈdʌk.ʃən/', 'Tax deductions are shown on your payslip.', 'n. | Salaries and Benefits', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 8, 1, @admin_id, NOW(), NOW()),
  (20083, 2009, 'Payslip', 'phiếu báo lương', '/ˈpeɪ.slɪp/', 'Check your digital payslip for breakdown.', 'n. | Salaries and Benefits', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 9, 1, @admin_id, NOW(), NOW()),
  (20084, 2009, 'Benefit', 'phúc lợi công ty', '/ˈben.ɪ.fɪt/', 'Employee benefits include paid sick leave.', 'n. | Salaries and Benefits', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 10, 1, @admin_id, NOW(), NOW()),
  (20085, 2009, 'Wage', 'tiền công tính theo giờ/ngày', '/weɪdʒ/', 'The minimum hourly wage was increased.', 'n. | Salaries and Benefits', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 12, 1, @admin_id, NOW(), NOW()),
  (20086, 2009, 'Reimbursement', 'sự hoàn tiền chi phí', '/ˌriː.ɪmˈbɜːs.mənt/', 'Submit travel receipts for expense reimbursement.', 'n. | Salaries and Benefits', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 13, 1, @admin_id, NOW(), NOW()),
  (20087, 2009, 'Commission', 'tiền hoa hồng bán hàng', '/kəˈmɪʃ.ən/', 'Reps earn a 5% commission on sales.', 'n. | Salaries and Benefits', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 14, 1, @admin_id, NOW(), NOW()),
  (20088, 2009, 'Perk', 'đặc quyền, đãi ngộ', '/pɜːk/', 'Free gym access is a great company perk.', 'n. | Salaries and Benefits', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 15, 1, @admin_id, NOW(), NOW()),
  (20089, 2010, 'Campaign', 'chiến dịch quảng cáo', '/kæmˈpeɪn/', 'The summer marketing campaign increased sales.', 'n. | Marketing', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 1, 1, @admin_id, NOW(), NOW()),
  (20090, 2010, 'Branding', 'xây dựng thương hiệu', '/ˈbræn.dɪŋ/', 'Consistent branding builds consumer trust.', 'n. | Marketing', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 2, 1, @admin_id, NOW(), NOW()),
  (20091, 2010, 'Demographic', 'nhóm nhân khẩu học', '/ˌdem.əˈɡræf.ɪk/', 'Target young adults as our core demographic.', 'n. | Marketing', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 3, 1, @admin_id, NOW(), NOW()),
  (20092, 2010, 'Flyer', 'tờ rơi quảng cáo', '/ˈflaɪ.ər/', 'Staff distributed promotional flyers on campus.', 'n. | Marketing', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 4, 1, @admin_id, NOW(), NOW()),
  (20093, 2010, 'Brochure', 'cẩm nang / tờ gấp giới thiệu', '/ˈbrəʊ.ʃər/', 'Pick up a product brochure at reception.', 'n. | Marketing', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 5, 1, @admin_id, NOW(), NOW()),
  (20094, 2010, 'Sponsor', 'tài trợ', '/ˈspɒn.sər/', 'The company decided to sponsor the sports event.', 'v. | Marketing', 'POS: v. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 7, 1, @admin_id, NOW(), NOW()),
  (20095, 2010, 'Advertisement', 'bài quảng cáo', '/ədˈvɜː.tɪs.mənt/', 'Place an advertisement in the daily newspaper.', 'n. | Marketing', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 9, 1, @admin_id, NOW(), NOW()),
  (20096, 2010, 'Consumer', 'người tiêu dùng', '/kənˈsjuː.mər/', 'Consumer demand for eco-friendly goods is high.', 'n. | Marketing', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 10, 1, @admin_id, NOW(), NOW()),
  (20097, 2010, 'Market research', 'nghiên cứu thị trường', '/ˈmɑː.kɪt rɪˈsɜːtʃ/', 'Market research revealed new growth areas.', 'n. | Marketing', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 11, 1, @admin_id, NOW(), NOW()),
  (20098, 2010, 'Strategy', 'chiến lược', '/ˈstræt.ə.dʒi/', 'Develop an effective social media strategy.', 'n. | Marketing', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 12, 1, @admin_id, NOW(), NOW()),
  (20099, 2010, 'Target', 'mục tiêu', '/ˈtɑː.ɡɪt/', 'We reached our quarterly sales target.', 'n. | Marketing', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 13, 1, @admin_id, NOW(), NOW()),
  (20100, 2010, 'Discount', 'sự giảm giá', '/ˈdɪs.kaʊnt/', 'Enjoy a 10% discount on your first order.', 'n. | Marketing', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 15, 1, @admin_id, NOW(), NOW());
INSERT INTO flashcards (id, deck_id, front_text, back_text, phonetic, example_text, hint, note, card_order, is_active, created_by, created_at, updated_at) VALUES
  (20101, 2011, 'Cashier', 'nhân viên thu ngân', '/kæˈʃɪər/', 'Pay the cashier at counter number 3.', 'n. | Shopping', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 1, 1, @admin_id, NOW(), NOW()),
  (20102, 2011, 'Receipt', 'hóa đơn thanh toán', '/rɪˈsiːt/', 'Keep your purchase receipt for returns.', 'n. | Shopping', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 2, 1, @admin_id, NOW(), NOW()),
  (20103, 2011, 'Refund', 'sự hoàn tiền', '/ˈriː.fʌnd/', 'Customer service processed a full refund.', 'n. | Shopping', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 4, 1, @admin_id, NOW(), NOW()),
  (20104, 2011, 'Checkout', 'quầy thanh toán', '/ˈtʃek.aʊt/', 'Proceed to express checkout counter.', 'n. | Shopping', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 5, 1, @admin_id, NOW(), NOW()),
  (20105, 2011, 'Cart', 'xe đẩy mua hàng', '/kɑːt/', 'Fill your shopping cart with fresh groceries.', 'n. | Shopping', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 6, 1, @admin_id, NOW(), NOW()),
  (20106, 2011, 'Aisle', 'lối đi giữa các gian hàng', '/aɪl/', 'Dairy products are located in aisle 4.', 'n. | Shopping', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 7, 1, @admin_id, NOW(), NOW()),
  (20107, 2011, 'Vendor', 'người bán hàng / nhà cung cấp', '/ˈven.dər/', 'The vendor sells organic produce.', 'n. | Shopping', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 8, 1, @admin_id, NOW(), NOW()),
  (20108, 2011, 'Inventory', 'hàng tồn kho', '/ˈɪn.vən.tər.i/', 'Stores restock inventory before holidays.', 'n. | Shopping', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 10, 1, @admin_id, NOW(), NOW()),
  (20109, 2011, 'Exchange', 'đổi hàng', '/ɪksˈtʃeɪndʒ/', 'You can exchange the shirt for another size.', 'v. | Shopping', 'POS: v. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 11, 1, @admin_id, NOW(), NOW()),
  (20110, 2011, 'Purchase', 'mua sắm', '/ˈpɜː.tʃəs/', 'She purchased a computer online.', 'v. | Shopping', 'POS: v. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 12, 1, @admin_id, NOW(), NOW()),
  (20111, 2011, 'Warranty', 'phiếu bảo hành', '/ˈwɒr.ən.ti/', 'The appliance includes a one-year warranty.', 'n. | Shopping', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 13, 1, @admin_id, NOW(), NOW()),
  (20112, 2011, 'Customer', 'khách hàng', '/ˈkʌs.tə.mər/', 'Friendly service satisfies every customer.', 'n. | Shopping', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 15, 1, @admin_id, NOW(), NOW()),
  (20113, 2012, 'Venue', 'địa điểm tổ chức sự kiện', '/ˈven.juː/', 'The hotel ballroom is the conference venue.', 'n. | Event', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 1, 1, @admin_id, NOW(), NOW()),
  (20114, 2012, 'Catering', 'dịch vụ cung cấp tiệc / ăn uống', '/ˈkeɪ.tər.ɪŋ/', 'Catering services provided lunch for attendees.', 'n. | Event', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 2, 1, @admin_id, NOW(), NOW()),
  (20115, 2012, 'Attendee', 'người tham dự', '/ə.tenˈdiː/', 'Over 500 attendees gathered for the summit.', 'n. | Event', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 3, 1, @admin_id, NOW(), NOW()),
  (20116, 2012, 'Banquet', 'bữa tiệc lớn', '/ˈbæŋ.kwɪt/', 'An evening banquet was held to celebrate.', 'n. | Event', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 4, 1, @admin_id, NOW(), NOW()),
  (20117, 2012, 'Keynote', 'bài phát biểu chủ đạo', '/ˈkiː.nəʊt/', 'The CEO delivered the opening keynote speech.', 'n. | Event', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 5, 1, @admin_id, NOW(), NOW()),
  (20118, 2012, 'Host', 'chủ trì, đăng cai tổ chức', '/həʊst/', 'Our city will host the international tech expo.', 'v. | Event', 'POS: v. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 7, 1, @admin_id, NOW(), NOW()),
  (20119, 2012, 'Organizer', 'ban tổ chức', '/ˈɔː.ɡən.aɪ.zər/', 'Contact the event organizer for badge pick-up.', 'n. | Event', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 8, 1, @admin_id, NOW(), NOW()),
  (20120, 2012, 'Invitation', 'thư mời', '/ˌɪn.vɪˈteɪ.ʃən/', 'Send formal invitations to all delegates.', 'n. | Event', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 9, 1, @admin_id, NOW(), NOW()),
  (20121, 2012, 'Schedule', 'lịch trình chương trình', '/ˈʃed.juːl/', 'The event schedule is printed in the booklet.', 'n. | Event', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 10, 1, @admin_id, NOW(), NOW()),
  (20122, 2012, 'Exhibition', 'triển lãm', '/ˌek.sɪˈbɪʃ.ən/', 'Visit the trade exhibition at hall B.', 'n. | Event', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 11, 1, @admin_id, NOW(), NOW()),
  (20123, 2012, 'Participant', 'người tham gia', '/pɑːˈtɪs.ɪ.pənt/', 'Each participant received a souvenir bag.', 'n. | Event', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 12, 1, @admin_id, NOW(), NOW()),
  (20124, 2012, 'Agenda', 'chương trình nghị sự', '/əˈdʒen.də/', 'Review the meeting agenda before discussion.', 'n. | Event', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 13, 1, @admin_id, NOW(), NOW()),
  (20125, 2012, 'Reception', 'tiệc đón tiếp', '/rɪˈsep.ʃən/', 'A welcome reception begins at 7 PM.', 'n. | Event', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 15, 1, @admin_id, NOW(), NOW()),
