  (20129, 2013, 'Departure', 'sự khởi hành', '/dɪˈpɑː.tʃər/', 'Flight departure time is scheduled for 8 AM.', 'n. | Travel', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 4, 1, @admin_id, NOW(), NOW()),
  (20130, 2013, 'Arrival', 'sự đến nơi', '/əˈraɪ.vəl/', 'Check the flight arrival status board.', 'n. | Travel', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 5, 1, @admin_id, NOW(), NOW()),
  (20131, 2013, 'Destination', 'điểm đến', '/ˌdes.tɪˈneɪ.ʃən/', 'Tokyo is a top travel destination.', 'n. | Travel', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 6, 1, @admin_id, NOW(), NOW()),
  (20132, 2013, 'Customs', 'hải quan sân bay', '/ˈkʌs.təmz/', 'Declare goods when passing customs.', 'n. | Travel', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 7, 1, @admin_id, NOW(), NOW()),
