  (20135, 2013, 'Layover', 'thời gian quá cảnh', '/ˈleɪˌəʊ.vər/', 'We had a three-hour layover in Bangkok.', 'n. | Travel', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 11, 1, @admin_id, NOW(), NOW()),
  (20136, 2013, 'Reservation', 'sự đặt chỗ trước', '/ˌrez.əˈveɪ.ʃən/', 'Confirm your flight reservation online.', 'n. | Travel', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 12, 1, @admin_id, NOW(), NOW()),
  (20137, 2013, 'Excursion', 'chuyến tham quan ngắn', '/ɪkˈskɜː.ʃən/', 'Join the guided city tour excursion.', 'n. | Travel', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 14, 1, @admin_id, NOW(), NOW()),
  (20138, 2014, 'Concert', 'buổi hòa nhạc', '/ˈkɒn.sət/', 'Attend the classical concert at city hall.', 'n. | Music', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 3, 1, @admin_id, NOW(), NOW()),
