  (20140, 2014, 'Performance', 'buổi biểu diễn', '/pəˈfɔː.məns/', 'The band delivered an outstanding performance.', 'n. | Music', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 8, 1, @admin_id, NOW(), NOW()),
  (20141, 2014, 'Album', 'album nhạc', '/ˈæl.bəm/', 'The artist released a new studio album.', 'n. | Music', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 10, 1, @admin_id, NOW(), NOW()),
