  (20143, 2014, 'Tune', 'giai điệu vui tươi', '/tjuːn/', 'He hummed a familiar catchy tune.', 'n. | Music', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 12, 1, @admin_id, NOW(), NOW()),
  (20144, 2014, 'Audition', 'buổi thử giọng', '/ɔːˈdɪʃ.ən/', 'Over fifty singers attended the audition.', 'n. | Music', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 13, 1, @admin_id, NOW(), NOW()),
  (20145, 2014, 'Musician', 'nhạc sĩ, nghệ sĩ biểu diễn', '/mjuːˈzɪʃ.ən/', 'Talented musicians played live acoustic tracks.', 'n. | Music', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 14, 1, @admin_id, NOW(), NOW()),
  (20146, 2014, 'Track', 'bài hát trong album', '/træk/', 'Track 3 is the lead single of the record.', 'n. | Music', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 15, 1, @admin_id, NOW(), NOW()),
