  (20148, 2015, 'Guitar', 'đàn ghi-ta', '/ɡɪˈtɑːr/', 'He learned to play acoustic guitar at age ten.', 'n. | Musical Instruments', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 2, 1, @admin_id, NOW(), NOW()),
  (20149, 2015, 'Piano', 'đàn pi-a-nô', '/piˈæn.əʊ/', 'She practices piano every afternoon.', 'n. | Musical Instruments', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 3, 1, @admin_id, NOW(), NOW()),
