  (20151, 2015, 'Violin', 'đàn vĩ cầm / vi-ô-lông', '/ˌvaɪəˈlɪn/', 'The soloist played a violin concerto.', 'n. | Musical Instruments', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 5, 1, @admin_id, NOW(), NOW()),
