  (20153, 2015, 'Saxophone', 'kèn xắc-xô-phôn', '/ˈsæk.sə.fəʊn/', 'Jazz musicians often play the saxophone.', 'n. | Musical Instruments', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 7, 1, @admin_id, NOW(), NOW()),
  (20154, 2015, 'Trumpet', 'kèn trôm-pét', '/ˈtrʌm.pɪt/', 'The brass section includes three trumpets.', 'n. | Musical Instruments', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 8, 1, @admin_id, NOW(), NOW()),
  (20155, 2015, 'Keyboard', 'đàn phím điện tử', '/ˈkiː.bɔːd/', 'The electronic keyboard offers synthesized sounds.', 'n. | Musical Instruments', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 9, 1, @admin_id, NOW(), NOW()),
  (20156, 2015, 'Strings', 'dây đàn nhạc cụ', '/strɪŋz/', 'Replace worn guitar strings regularly.', 'n. | Musical Instruments', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 10, 1, @admin_id, NOW(), NOW()),
