  (20158, 2015, 'Acoustic', 'âm thanh mộc, không dùng điện', '/əˈkuː.stɪk/', 'They enjoyed an acoustic guitar performance.', 'adj. | Musical Instruments', 'POS: adj. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 12, 1, @admin_id, NOW(), NOW()),
  (20159, 2015, 'Amplifier', 'bộ khuếch đại âm thanh (âm-li)', '/ˈæm.plɪ.faɪ.ər/', 'Plug the electric guitar into the amplifier.', 'n. | Musical Instruments', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 13, 1, @admin_id, NOW(), NOW()),
  (20160, 2015, 'Microphone', 'micro nói / hát', '/ˈmaɪ.krə.fəʊn/', 'Speak clearly into the microphone.', 'n. | Musical Instruments', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 14, 1, @admin_id, NOW(), NOW()),
  (20161, 2015, 'Harmonica', 'kèn khẩu cầm (kèn ét-môn-ni-ca)', '/hɑːˈmɒn.ɪ.kə/', 'He played a blues tune on his harmonica.', 'n. | Musical Instruments', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 15, 1, @admin_id, NOW(), NOW()),
