  (20163, 2016, 'Screenplay', 'kịch bản phim', '/ˈskriːn.pleɪ/', 'The writer won an award for best screenplay.', 'n. | Movie', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 2, 1, @admin_id, NOW(), NOW()),
  (20164, 2016, 'Director', 'đạo diễn phim', '/daɪˈrek.tər/', 'The film director instructed the actors.', 'n. | Movie', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 3, 1, @admin_id, NOW(), NOW()),
  (20165, 2016, 'Producer', 'nhà sản xuất phim', '/prəˈdʒuː.sər/', 'The movie producer secured production funds.', 'n. | Movie', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 4, 1, @admin_id, NOW(), NOW()),
  (20166, 2016, 'Subtitle', 'phụ đề phim', '/ˈsʌbˌtaɪ.təl/', 'Foreign films include English subtitles.', 'n. | Movie', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 5, 1, @admin_id, NOW(), NOW()),
