  (20169, 2016, 'Actor', 'nam diễn viên', '/ˈæk.tər/', 'The lead actor starred in five hit films.', 'n. | Movie', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 9, 1, @admin_id, NOW(), NOW()),
