  (20171, 2016, 'Scene', 'cảnh phim', '/siːn/', 'They filmed the final action scene in London.', 'n. | Movie', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 11, 1, @admin_id, NOW(), NOW()),
