  (20174, 2016, 'Sequel', 'phần phim tiếp theo', '/ˈsiː.kwəl/', 'The movie sequel was released two years later.', 'n. | Movie', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 14, 1, @admin_id, NOW(), NOW()),
  (20175, 2016, 'Studio', 'xưởng phim, phim trường', '/ˈstjuː.di.əʊ/', 'The film studio constructed impressive movie sets.', 'n. | Movie', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 15, 1, @admin_id, NOW(), NOW()),
  (20176, 2017, 'Reservation', 'sự đặt phòng khách sạn', '/ˌrez.əˈveɪ.ʃən/', 'I have a room reservation under the name Smith.', 'n. | Hotel', 'POS: n. | Level: TOEIC Dưới 500 | Source: TOEIC Vocabulary 600', 1, 1, @admin_id, NOW(), NOW()),
