  (100494, 10033, 'Chọn từ đúng điền vào chỗ trống: "The hotel valet parked our rental car."', 'MULTIPLE_CHOICE', 10, 14, 'Đáp án đúng là ''Valet'' (dịch vụ đỗ xe cho khách). Câu hoàn chỉnh: The hotel valet parked our rental car.', 1, NOW(), NOW()),
  (100495, 10033, 'Từ tiếng Anh nào có nghĩa là ''tiền đặt cọc phòng'' (n.)?', 'MULTIPLE_CHOICE', 10, 15, 'Nghĩa ''tiền đặt cọc phòng'' tương ứng với từ tiếng Anh ''Deposit''.', 1, NOW(), NOW()),
  (100496, 10034, 'Từ ''Reservation'' (n.) có nghĩa là gì trong tiếng Việt?', 'MULTIPLE_CHOICE', 10, 1, '''Reservation'' (n.) nghĩa là: sự đặt phòng khách sạn. Ví dụ: I have a room reservation under the name Smith.', 1, NOW(), NOW()),
  (100497, 10034, 'Chọn từ đúng điền vào chỗ trống: "The receptionist handed me the electronic room key."', 'MULTIPLE_CHOICE', 10, 2, 'Đáp án đúng là ''Receptionist'' (nhân viên lễ tân khách sạn). Câu hoàn chỉnh: The receptionist handed me the electronic room key.', 1, NOW(), NOW()),
  (100498, 10034, 'Từ tiếng Anh nào có nghĩa là ''phòng thượng hạng / phòng suite'' (n.)?', 'MULTIPLE_CHOICE', 10, 3, 'Nghĩa ''phòng thượng hạng / phòng suite'' tương ứng với từ tiếng Anh ''Suite''.', 1, NOW(), NOW()),
  (100499, 10034, 'Từ ''Housekeeping'' (n.) có nghĩa là gì trong tiếng Việt?', 'MULTIPLE_CHOICE', 10, 4, '''Housekeeping'' (n.) nghĩa là: bộ phận dọn phòng khách sạn. Ví dụ: Housekeeping cleans and sanitizes rooms daily.', 1, NOW(), NOW()),
  (100500, 10034, 'Chọn từ đúng điền vào chỗ trống: "Ask the concierge to arrange taxi transport."', 'MULTIPLE_CHOICE', 10, 5, 'Đáp án đúng là ''Concierge'' (nhân viên hỗ trợ khách hàng tại khách sạn). Câu hoàn chỉnh: Ask the concierge to arrange taxi transport.', 1, NOW(), NOW());
